import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asOfKey, asOfPath, sheetKey } from '../sheet/sheet';
import { useAsOf } from '../../session/session';

/** A user name's role on the sheet. A name with none assigned is a clerk; a viewer may change nothing;
 *  a restricted user acts as a clerk but sees on the people list only its own and its crews' people. */
export type Role = { user: string; role: string };

export const ROLES = ['clerk', 'steward', 'viewer', 'restricted'] as const;

/** Under the sheet's key, so loading the sheet again re-reads its roles. */
export const rolesKey = (sheet: string) => [...sheetKey(sheet), 'roles'] as const;

export function useRoles(sheet: string) {
  const [asOf] = useAsOf();
  return useQuery({
    queryKey: asOfKey(rolesKey(sheet), asOf),
    queryFn: () => getJson<Role[]>(asOfPath(`/api/sheets/${encodeURIComponent(sheet)}/roles`, asOf)),
    enabled: sheet !== '',
  });
}

/** The steward role delegated to `user` by the steward `by` for from..to (yyyy-mm-dd), inclusive. */
export type Delegation = { user: string; from: string; to: string; by: string };

export const delegationsKey = (sheet: string) => [...sheetKey(sheet), 'delegations'] as const;

export function useDelegations(sheet: string) {
  const [asOf] = useAsOf();
  return useQuery({
    queryKey: asOfKey(delegationsKey(sheet), asOf),
    queryFn: () => getJson<Delegation[]>(asOfPath(`/api/sheets/${encodeURIComponent(sheet)}/delegations`, asOf)),
    enabled: sheet !== '',
  });
}
}

function SortBy() {
  const [by, setBy] = useSortBy();
  return (
    <label>
      Sort by{' '}
      <select data-testid="sort-by" value={by} onChange={(e) => setBy(e.target.value as Sort)}>
        {SORTS.map((s) => (
          <option key={s} value={s}>
            {s}
          </option>
        ))}
      </select>
    </label>
  );
}

// The sheet's people in list order (by their positions, see move.slot.tsx); retired people only while "show retired" is on.
function PeopleList() {
  const [sheet] = useCurrentSheet();
  const [, setEditing] = useEditingPerson();
  const people = usePeople(sheet);
  const [showRetired] = useShowRetired();
  const [selected, setSelected] = useSelectedPeople();
  const [sortBy] = useSortBy();
  const dueOf = usePersonDue(sheet);
  const shown = useColumnShown();
  const visible = useRowVisible(sheet);

  return (
    <>
    <SortBy />
    <table data-testid="people">
      <thead>
        <tr>
          <th />
          <th>Name</th>
          <th>Grade</th>
          {shown('terms') && <th>Terms</th>}
          {shown('contact') && <th>Contact</th>}
          <th>Tags</th>
          <th>Snapshots</th>
          <th>Clashing</th>
          <PersonColumnHeads.Slot />
          <th />
        </tr>
      </thead>
      <tbody>
        {sorted(people.data ?? [], sortBy, dueOf).filter((p) => (showRetired || !p.retired) && visible(p)).map((p) => (
          <tr key={p.id} data-testid={`person-row-${p.id}`}>
            <td>
              <input
                type="checkbox"
                data-testid="person-select"
                aria-label="Select person"
                checked={selected.includes(p.id)}
                onChange={(e) => setSelected(e.target.checked ? [...selected, p.id] : selected.filter((id) => id !== p.id))}
              />
            </td>
            <td data-testid="person-name" style={{ whiteSpace: 'pre' }}>{shownName(p)}</td>
            <td data-testid="person-grade">{p.grade}</td>
            {shown('terms') && <td data-testid="person-terms">{p.terms ?? ''}</td>}
            {shown('contact') && <td data-testid="person-contact">{p.contact ?? ''}</td>}
            <td data-testid="person-tags">{p.tags.join(', ')}</td>
            <td>
              {p.snapshots.map((n, i) => (
                <div key={i} data-testid="person-snapshot-line">
                  {n.day} {n.dueTotal}
                </div>
              ))}
            </td>
            <td data-testid="person-clashing">{p.clashing ? 'yes' : 'no'}</td>
            <PersonColumns.Slot person={p} />
            <td>
              <button type="button" data-testid={`person-edit-${p.id}`} onClick={() => setEditing(String(p.id))}>
                Edit
              </button>
            </td>
          </tr>
        ))}

